import {TEAMS as DEFAULT_TEAMS,STATUSES,USERS as DEFAULT_USERS,uid,seed,priority,blockedBy,completionIssue,customerSnapshot,parseEmail,moveTask} from './domain.js?v=4';
const KEY='inboxy.workspace.v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();if(state.version!==1||!Array.isArray(state.tasks))throw Error();}catch{state=seed();}
function migrateWorkspace(data){
 data.groups ??= DEFAULT_TEAMS.map((name,i)=>({id:'group-'+i,name,description:({Ops:'Coordinate requests and shipment handoffs',Warehouse:'Prepare cargo and complete physical work',Accounting:'Charges, invoices and follow-ups',Pricing:'Quotes, rates and approvals'})[name],members:DEFAULT_USERS.filter(n=>n!=='Unassigned'&&data.tasks.some(t=>t.team===name&&t.owner===n))}));
 data.people ??= DEFAULT_USERS.filter(n=>n!=='Unassigned').map((name,i)=>({id:'person-'+i,name,email:'',role:i===0?'Admin':'Member'}));
 return data;
}
migrateWorkspace(state);
let TEAMS=[],USERS=[];
function syncDirectory(){TEAMS=state.groups.map(g=>g.name);USERS=['Unassigned',...state.people.map(p=>p.name)];}
syncDirectory();
let page='workspace',view='Board',team='All teams',owner='All owners',query='',attention=false,selectedEmail=state.emails[0]?.id;
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>s==='Unassigned'?'?':s.slice(0,2).toUpperCase();
const fmt=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'No date';
const shipment=id=>state.shipments.find(s=>s.id===id);
const options=(values,current)=>values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');
function toast(s){const dialog=$('#detail');if(dialog.open){let message=dialog.querySelector('[data-feedback]');if(!message){message=document.createElement('div');message.dataset.feedback='true';message.className='notice';message.setAttribute('role','status');dialog.querySelector('.dialog-head').after(message);}message.textContent=s;}$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3800);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Storage is full or unavailable. Export a backup before closing.');return false;}}
function activity(t,text){t.activity.unshift({text,date:new Date().toISOString()});}
function openDialog(title,body,footer=''){const d=$('#detail');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-close aria-label="Close dialog">✕</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();}
function filtered(){return state.tasks.filter(t=>(team==='All teams'||t.team===team)&&(owner==='All owners'||t.owner===owner)&&(!query||[t.title,t.nextAction,t.description,shipment(t.shipmentId)?.reference,shipment(t.shipmentId)?.customer].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!attention||priority(t,state.tasks).reasons.some(r=>['Overdue','Follow-up due','Needs owner'].includes(r)))).sort((a,b)=>priority(b,state.tasks).score-priority(a,state.tasks).score);}
function render(){
const active=state.tasks.filter(t=>t.status!=='Completed'); const overdue=active.filter(t=>t.due&&new Date(t.due)<new Date());const follow=active.filter(t=>t.followUp&&new Date(t.followUp)<=new Date());
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo">inboxy<b>↗</b><small>OPERATIONS, CONNECTED</small></div><div class="workspace">N10 Logistics <span>Operations workspace · Demo</span></div><nav class="nav" aria-label="Workspace"><button data-page="workspace" class="${page==='workspace'?'active':''}"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4"/><path d="M9 3v18M15 3v18"/></svg> <span>Workspace</span><span class="count">${active.length}</span></button><button data-page="inbox" class="${page==='inbox'?'active':''}"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/></svg> <span>Email inbox</span><span class="count">${state.emails.filter(e=>!e.taskId).length}</span></button><button data-page="shipments" class="${page==='shipments'?'active':''}"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 9 5v9l-9 5-9-5V8Z"/><path d="m3 8 9 5 9-5M12 13v9M7.5 5.5l9 5"/></svg> <span>Shipments</span></button><button data-page="workload" class="${page==='workload'?'active':''}"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 3v9l6 6"/></svg> <span>Team workload</span></button><label>TEAM QUEUES</label>${TEAMS.map(t=>`<button data-team="${esc(t)}" class="${team===t&&page==='workspace'?'active':''}"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="5" width="14" height="14" rx="4"/></svg> <span>${esc(t)}</span><span class="count">${active.filter(x=>x.team===t).length}</span></button>`).join('')}<label>WORKSPACE</label><button data-page="groups" class="${page==='groups'?'active':''}">＋ <span>Groups & people</span></button><button data-page="settings" class="${page==='settings'?'active':''}"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="16" cy="17" r="3" fill="white"/></svg> <span>Connections & data</span></button></nav><footer><span class="avatar">IA</span> Ignacio<br><span>Keep every handoff visible.</span></footer></aside><main class="main"><header class="topbar"><input class="search" id="search" aria-label="Search tasks, customers, references" placeholder="Search tasks, customers, references…" value="${esc(query)}"><div class="topbar-right"><span class="demo">Local workspace</span><span class="avatar">IA</span></div></header><div class="content"><div class="eyebrow">N10 / OPERATIONS</div><div class="heading"><div><h1>${({workspace:team==='All teams'?'Operations inbox':team+' space',inbox:'Email inbox',shipments:'Shipments',workload:'Team workload',settings:'Workspace settings',groups:'Built around your people.'})[page]}</h1><p class="muted">${({workspace:'Less chasing. Clear ownership. Every handoff in sight.',inbox:'Capture requests and keep the original instructions close.',shipments:'Keep tasks, handoffs, and customer updates together.',workload:'Spot overloaded queues and rebalance the work.',settings:'Manage local data and plan your live connections.',groups:'Create your groups. Bring in your people. Give every request a home.'})[page]}</p></div><div class="actions">${page==='groups'?'<button id="new-group">＋ New group</button><button id="new-person" class="primary">＋ Add person</button>':''}${page==='inbox'?'<button id="capture">＋ Capture email</button>':''}${page==='shipments'?'<button class="primary" id="new-shipment">＋ New shipment</button>':page==='groups'?'':'<button class="primary" id="new-task">＋ New task</button>'}</div></div>${page==='workspace'?`${overviewHTML(active)}<div class="toolbar"><div class="segments">${['Focus','Board','List','Do next'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}">${v==='Board'?'▦':v==='List'?'☷':'↗'} ${v}</button>`).join('')}</div><div class="filters"><select id="team" aria-label="Filter by team">${options(['All teams',...TEAMS],team)}</select><select id="owner" aria-label="Filter by owner">${options(['All owners',...USERS],owner)}</select><button id="clear" class="small">Clear filters</button></div></div><div id="task-results">${taskResults()}</div><div class="bottom-note">${attention?'Showing overdue, unassigned, and follow-up-due tasks. ':''}Local demo: changes stay in this browser. Team filters are views, not access permissions.</div>`:page==='inbox'?inboxHTML():page==='shipments'?shipmentsHTML():page==='workload'?workloadHTML():page==='groups'?groupsHTML():settingsHTML()}</div></main></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{team=b.dataset.team;page='workspace';attention=false;render();});
 $('#search').oninput=e=>{query=e.target.value;if(page!=='workspace'){page='workspace';render();$('#search').focus();}else{$('#task-results').innerHTML=taskResults();bindCards();bindPage();bindDirectory();}};
 $('#new-task')?.addEventListener('click',()=>quickTask());$('#new-shipment')?.addEventListener('click',()=>shipmentEditor());$('#capture')?.addEventListener('click',captureEmail);$('#new-group')?.addEventListener('click',()=>groupEditor());$('#new-person')?.addEventListener('click',()=>personEditor());
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#team')?.addEventListener('change',e=>{team=e.target.value;render();});$('#owner')?.addEventListener('change',e=>{owner=e.target.value;render();});$('#attention')?.addEventListener('click',()=>{attention=!attention;view='Do next';render();});$('#clear')?.addEventListener('click',()=>{team='All teams';owner='All owners';query='';attention=false;render();});
 bindCards();bindPage();bindDirectory();
}
function card(t){const s=shipment(t.shipmentId),blocks=blockedBy(t,state.tasks),children=state.tasks.filter(x=>x.parentId===t.id),emails=state.emails.filter(e=>e.taskId===t.id);return `<article class="card operation-card priority-${t.priority.toLowerCase()} ${blocks.length?'has-blockers':''} ${t.status==='Completed'?'is-complete':''}" draggable="true" tabindex="0" role="group" data-task="${t.id}" aria-label="${esc(t.title)}"><div class="card-context"><span class="ref">${esc(s?.reference||'GENERAL REQUEST')}</span><button class="drag-handle" data-drag="${t.id}" aria-label="Drag ${esc(t.title)}" title="Drag to move or reorder" draggable="false">⠿</button></div><button class="card-open"><h3>${esc(t.title)}</h3></button><div class="customer">${esc(s?.customer||t.team)}${t.parentId?' · Subtask':''}</div><button class="next-action" data-quick-edit="${t.id}"><span>NEXT</span><strong>${esc(t.nextAction||'Add next action')}</strong><span>↗</span></button>${blocks.length?`<div class="blocked-line">↳ Waiting on ${esc(blocks[0].title)}${blocks.length>1?' +'+(blocks.length-1):''}</div>`:''}<div class="card-signals"><span class="badge ${t.priority}">${esc(t.priority)}</span>${t.due&&new Date(t.due)<new Date()&&t.status!=='Completed'?'<span class="overdue-pill">Overdue</span>':''}${children.length?`<span>☑ ${children.filter(c=>c.status==='Completed').length}/${children.length}</span>`:''}${emails.length?`<button data-card-email="${t.id}">✉ ${emails.length}</button>`:''}${t.followUp?`<span title="Follow-up">↻ ${esc(fmt(t.followUp))}</span>`:''}</div><div class="card-bottom"><button class="card-owner" data-quick-edit="${t.id}"><span class="avatar">${esc(initials(t.owner))}</span>${esc(t.owner)}</button><button class="card-due ${t.due&&new Date(t.due)<new Date()&&t.status!=='Completed'?'overdue':''}" data-quick-edit="${t.id}">${t.due?esc(fmt(t.due)):'＋ Due date'}</button></div><label class="card-move"><span>Move to</span><select data-move="${t.id}" aria-label="Move ${esc(t.title)} to status">${options(STATUSES,t.status)}</select></label></article>`;}
function taskResults(){let list=filtered();if(view==='Do next')list=list.filter(t=>t.status!=='Completed');if(!list.length&&view!=='Board')return '<div class="panel empty">No tasks match these filters.</div>';if(view==='Focus')return focusHTML(list);if(view==='Board')return `<div class="board-guidance"><span>Drag cards between columns. Drag the grip to move on touch screens.</span><span>Or use “Move to” on any card.</span></div><div class="board">${STATUSES.map(status=>`<section class="column" data-status="${status}" aria-label="${status} column"><div class="column-head"><i class="dot"></i>${status}<span class="number">${list.filter(t=>t.status===status).length}</span><button class="column-add" data-add-status="${status}" aria-label="Add task to ${status}">＋</button></div><div class="column-cards">${list.filter(t=>t.status===status).sort((a,b)=>(a.boardOrder??state.tasks.indexOf(a))-(b.boardOrder??state.tasks.indexOf(b))).map(card).join('')||'<div class="drop-placeholder">Drop a task here</div>'}</div><form class="column-quick-add" data-quick-status="${status}"><input name="title" required maxlength="180" aria-label="New task in ${status}" placeholder="＋ Add a task…"><button type="submit" aria-label="Create task in ${status}">↵</button></form></section>`).join('')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>Task / next action</th><th>Reference</th><th>Team / owner</th><th>Status</th><th>Due</th><th>Priority reason</th></tr></thead><tbody>${list.map(t=>`<tr tabindex="0" data-task="${t.id}"><td><strong>${esc(t.title)}</strong><p class="muted">${esc(t.nextAction||'Define next action')}</p></td><td>${esc(shipment(t.shipmentId)?.reference||'—')}</td><td>${esc(t.team)}<br>${esc(t.owner)}</td><td><span class="badge">${t.status}</span></td><td>${esc(fmt(t.due))}</td><td>${esc(priority(t,state.tasks).reasons.join(' · '))}</td></tr>`).join('')}</tbody></table></div>`;}
function bindCards(){document.querySelectorAll('[data-task]').forEach(b=>{b.onclick=e=>{if(e.target.closest('button,select,input')&&!e.target.closest('.card-open'))return;taskDetail(b.dataset.task);};b.onkeydown=e=>{if(e.target===b&&(e.key==='Enter'||e.key===' ')){e.preventDefault();taskDetail(b.dataset.task);}};});bindBoard();}
function taskEditor(id,defaults={}){const t=id?state.tasks.find(t=>t.id===id):{title:'',shipmentId:defaults.shipmentId||'',team:team==='All teams'?'Ops':team,owner:'Unassigned',status:'Up next',priority:'Normal',due:'',followUp:'',nextAction:'',description:'',parentId:defaults.parentId||null,dependencies:[],public:false,publicTitle:'',impact:false};
openDialog(id?'Edit task':'Create a task',`<form id="task-form" class="form-grid"><label class="field full">Task title<input name="title" required maxlength="180" value="${esc(t.title)}" placeholder="What needs to happen?"></label><label class="field">Shipment / operational record<select name="shipmentId"><option value="">General request</option>${state.shipments.map(s=>`<option value="${s.id}" ${t.shipmentId===s.id?'selected':''}>${esc(s.reference+' · '+s.customer)}</option>`).join('')}</select></label><label class="field">Team<select name="team">${options(TEAMS,t.team)}</select></label><label class="field">Owner<select name="owner">${options(USERS,t.owner)}</select></label><label class="field">Status<select name="status">${options(STATUSES,t.status)}</select></label><label class="field">Priority<select name="priority">${options(['Urgent','High','Normal','Low'],t.priority)}</select></label><label class="field">Deadline<input type="datetime-local" name="due" value="${esc(t.due)}"></label><label class="field">Follow up at<input type="datetime-local" name="followUp" value="${esc(t.followUp)}"></label><label class="field">Next action<input name="nextAction" value="${esc(t.nextAction)}" placeholder="A clear, concrete next step"></label><label class="field full">Operational instructions<textarea name="description">${esc(t.description)}</textarea></label><label class="field full">Blocked by (hold Ctrl / ⌘ to select multiple)<select name="dependencies" multiple size="3">${state.tasks.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${t.dependencies.includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label class="check-row full"><input type="checkbox" name="impact" ${t.impact?'checked':''}> Operational impact: cutoff, hold, cost, or appointment risk</label><label class="check-row full"><input type="checkbox" name="public" ${t.public?'checked':''}> Include this milestone in the customer preview</label><label class="field full">Customer-facing milestone title<input name="publicTitle" value="${esc(t.publicTitle)}" placeholder="Use a customer-safe title"></label></form>`,`<button data-cancel>Cancel</button><button type="submit" form="task-form" class="primary">${id?'Save changes':'Create task'}</button>`);
 $('[data-cancel]').onclick=()=>$('#detail').close();$('#task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const changes=Object.fromEntries(f);changes.dependencies=f.getAll('dependencies');changes.public=f.has('public');changes.impact=f.has('impact');changes.title=changes.title.trim();if(!changes.title)return toast('Add a task title.');if(changes.dependencies.some(dep=>hasDependencyPath(dep,id)))return toast('This dependency would create a cycle.');if(changes.status==='Completed'){const issue=completionIssue({...t,...changes},state.tasks);if(issue)return toast(issue);}const now=new Date().toISOString();if(id){Object.assign(t,changes);activity(t,'Task updated');}else{const nt={...t,...changes,id:uid(),notes:[],activity:[{text:'Task created',date:now}]};state.tasks.push(nt);if(defaults.emailId){state.emails.find(x=>x.id===defaults.emailId).taskId=nt.id;}}save();$('#detail').close();render();toast('Task saved');};}
function hasDependencyPath(start,target,visited=new Set()){if(!target)return false;if(start===target)return true;if(visited.has(start))return false;visited.add(start);return state.tasks.find(t=>t.id===start)?.dependencies.some(d=>hasDependencyPath(d,target,visited))||false;}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;const s=shipment(t.shipmentId),children=state.tasks.filter(x=>x.parentId===id),emails=state.emails.filter(x=>x.taskId===id),blocks=blockedBy(t,state.tasks);
openDialog('Task details',`<div class="actions"><span class="badge ${t.priority}">${esc(t.priority)}</span><span class="badge">${esc(t.team)}</span><span class="badge">${esc(t.status)}</span></div><h2>${esc(t.title)}</h2><p class="muted">${esc(s?s.reference+' · '+s.customer:'General request')} · ${esc(t.owner)} · Due ${esc(fmt(t.due))}</p>${t.parentId?`<p><button class="linkbutton" id="parent-task">↑ Open parent task</button></p>`:''}${blocks.length?`<div class="notice">Waiting on: ${blocks.map(b=>esc(b.title)).join(' · ')}</div>`:''}<p>${esc(t.description||'No operational instructions yet.')}</p><div class="note"><strong>Next action</strong><p>${esc(t.nextAction||'Define the next action')}</p>${t.followUp?`Follow up: ${esc(fmt(t.followUp))}`:''}</div><div class="section-title"><h3>Subtasks <span class="muted">${children.filter(x=>x.status==='Completed').length}/${children.length}</span></h3><button id="add-subtask">＋ Add subtask</button></div>${children.map(c=>`<div class="check-row"><span class="badge">${c.status==='Completed'?'✓': '○'}</span><span>${esc(c.title)}<small class="muted"> · ${esc(c.team)} / ${esc(c.owner)}</small></span><button data-child="${c.id}" class="small">Open</button></div>`).join('')||'<p class="muted">Break this work into clear team handoffs.</p>'}<div class="section-title"><h3>Linked conversations</h3><button id="link-email">Link email</button></div>${emails.map(e=>`<div class="note"><strong>${esc(e.subject)}</strong><small>${esc(e.from)}</small><p>${esc(e.body)}</p><button data-reply="${e.id}">Draft reply ↗</button></div>`).join('')||'<p class="muted">No emails linked to this task.</p>'}<h3>Internal notes</h3>${t.notes.map(n=>`<div class="note">${esc(n.body)}<small>${esc(n.author)} · ${esc(fmt(n.date))}</small></div>`).join('')}<form id="note-form" class="inline-form"><textarea name="note" aria-label="Internal note" required placeholder="Add an internal note…"></textarea><button>Add note</button></form><h3>Activity</h3>${t.activity.map(a=>`<p class="muted">${esc(a.text)} · ${esc(fmt(a.date))}</p>`).join('')||'<p class="muted">No activity yet.</p>'}`,`<button id="edit-task">Edit task</button>${s?'<button id="share-task">Customer update</button>':''}${t.status!=='Completed'?'<button id="complete-task" class="primary">Mark complete</button>':''}`);
 $('#edit-task').onclick=()=>taskEditor(id);$('#add-subtask').onclick=()=>quickTask({parentId:id,shipmentId:t.shipmentId});$('#parent-task')?.addEventListener('click',()=>taskDetail(t.parentId));document.querySelectorAll('[data-child]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.child));document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>draftReply(b.dataset.reply));$('#share-task')?.addEventListener('click',()=>customerView(s.id));$('#link-email').onclick=()=>linkEmail(id);$('#complete-task')?.addEventListener('click',()=>{const issue=moveTask(state.tasks,id,'Completed');if(issue)return toast(issue);activity(t,'Marked complete');save();render();taskDetail(id);toast('Completed — dependent tasks can now move forward');});$('#note-form').onsubmit=e=>{e.preventDefault();const body=new FormData(e.target).get('note').trim();if(!body)return;t.notes.push({body,author:'Ignacio',date:new Date().toISOString()});activity(t,'Internal note added');save();taskDetail(id);};}
function inboxHTML(){const e=state.emails.find(e=>e.id===selectedEmail);return `<div class="notice" style="margin-bottom:18px">Email capture is manual in this version. Import a plain-text .eml or paste a message. Live Gmail / Microsoft 365 sync is not connected.</div><div class="mail"><div class="mail-list">${state.emails.map(e=>`<button class="mail-row ${e.id===selectedEmail?'selected':''}" data-email="${e.id}"><small>${esc(e.from)}</small><strong>${esc(e.subject)}</strong><span class="badge">${e.taskId?'Linked to task':'Needs review'}</span></button>`).join('')||'<p class="empty">No captured emails yet.</p>'}</div><div class="mail-body">${e?`<span class="eyebrow">CAPTURED EMAIL</span><h2>${esc(e.subject)}</h2><p class="muted">${esc(e.from)}</p><pre>${esc(e.body)}</pre><div class="actions">${e.taskId?`<button class="primary" id="open-linked">Open linked task</button>`:'<button class="primary" id="email-task">Create task</button><button id="email-link">Link to existing task</button>'}<button id="email-reply">Draft reply</button></div>`:'<p class="muted">Select a conversation to review.</p>'}</div></div><h2>Saved reply drafts</h2>${state.drafts.map(d=>`<div class="panel"><strong>${esc(d.subject)}</strong><p class="muted">To: ${esc(d.to)} · Saved ${esc(fmt(d.date))} · Not sent</p><p style="white-space:pre-wrap">${esc(d.body)}</p></div>`).join('')||'<p class="muted">Replies you draft will appear here. Nothing is sent automatically.</p>'}`;}
function captureEmail(){openDialog('Capture an email',`<div class="notice">Plain-text .eml imports only; attachments and encoded email formats are not imported. You can also paste the message below.</div><p><input id="eml" type="file" accept=".eml,text/plain" aria-label="Import plain-text email"></p><form id="email-form" class="form-grid"><label class="field full">From<input name="from" required placeholder="Name <email@example.com>"></label><label class="field full">Subject<input name="subject" required></label><label class="field full">Email body<textarea name="body" required></textarea></label></form>`,`<button class="primary" type="submit" form="email-form">Capture email</button>`);$('#eml').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000)return toast('Use a plain-text email under 1 MB.');try{const mail=parseEmail(await file.text());const f=$('#email-form');for(const k of ['from','subject','body'])f.elements[k].value=mail[k];toast('Email loaded — review and capture');}catch(err){toast(err.message);}};$('#email-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.subject.trim()||!data.body.trim())return;const email={...data,id:uid(),date:new Date().toISOString(),taskId:null};state.emails.unshift(email);selectedEmail=email.id;save();$('#detail').close();render();toast('Email captured');};}
function linkEmail(taskId){openDialog('Link conversation',`<form id="link-form" class="form-grid"><label class="field full">Captured email<select name="email">${state.emails.filter(e=>!e.taskId||e.taskId===taskId).map(e=>`<option value="${e.id}">${esc(e.subject)}</option>`).join('')}</select></label></form>`,`<button type="submit" form="link-form" class="primary">Link email</button>`);$('#link-form').onsubmit=e=>{e.preventDefault();const email=state.emails.find(x=>x.id===new FormData(e.target).get('email'));if(!email)return toast('Capture an email first.');email.taskId=taskId;save();taskDetail(taskId);};}
function draftReply(emailId){const e=state.emails.find(x=>x.id===emailId);openDialog('Draft a reply',`<div class="notice">This is a local draft. You can open it in your email app to review and send. Inboxy does not send or sync replies yet.</div><form id="reply-form" class="form-grid" style="margin-top:18px"><label class="field full">To<input name="to" type="email" required value="${esc(e.from.match(/<([^>]+)>/)?.[1]||e.from)}"></label><label class="field full">Subject<input name="subject" required value="${esc(/^re:/i.test(e.subject)?e.subject:'Re: '+e.subject)}"></label><label class="field full">Message<textarea name="body" required style="min-height:180px"></textarea></label></form>`,`<button id="open-mail">Open in email app</button><button class="primary" type="submit" form="reply-form">Save draft</button>`);const read=()=>Object.fromEntries(new FormData($('#reply-form')));$('#open-mail').onclick=()=>{if(!$('#reply-form').reportValidity())return;const d=read();location.href=`mailto:${encodeURIComponent(d.to)}?subject=${encodeURIComponent(d.subject)}&body=${encodeURIComponent(d.body)}`;};$('#reply-form').onsubmit=ev=>{ev.preventDefault();state.drafts.unshift({...read(),id:uid(),emailId,date:new Date().toISOString()});save();$('#detail').close();render();toast('Draft saved locally — not sent');};}
function shipmentsHTML(){return `<div class="shipment-grid">${state.shipments.map(s=>{const tasks=state.tasks.filter(t=>t.shipmentId===s.id),done=tasks.filter(t=>t.status==='Completed').length;return `<section class="panel"><span class="eyebrow">${esc(s.reference)}</span><h2>${esc(s.customer)}</h2><p class="muted">${esc(s.route)}<br>${esc(s.container||'No container reference')}</p><span class="badge">${esc(s.publicStatus)}</span><div class="progress"><i style="width:${tasks.length?done/tasks.length*100:0}%"></i></div><p class="muted">${done} of ${tasks.length} tasks complete · ${tasks.filter(t=>blockedBy(t,state.tasks).length).length} blocked</p><div class="actions"><button data-shipment="${s.id}">View work</button><button data-customer="${s.id}">Customer update ↗</button><button data-edit-shipment="${s.id}" aria-label="Edit ${esc(s.reference)}">Edit</button></div></section>`;}).join('')}</div>`;}
function shipmentEditor(id){const s=shipment(id)||{reference:'',customer:'',route:'',container:'',publicStatus:'Request received',publicUpdate:'',nextUpdate:''};openDialog(id?'Edit shipment':'New shipment',`<form id="shipment-form" class="form-grid">${[['reference','Reference'],['customer','Customer'],['route','Route'],['container','Container / booking reference'],['publicStatus','Customer-facing status']].map(([k,l])=>`<label class="field">${l}<input name="${k}" value="${esc(s[k])}" ${['reference','customer','publicStatus'].includes(k)?'required':''}></label>`).join('')}<label class="field">Next customer update<input name="nextUpdate" type="datetime-local" value="${esc(s.nextUpdate)}"></label><label class="field full">Customer-facing update<textarea name="publicUpdate">${esc(s.publicUpdate)}</textarea></label></form>`,`<button class="primary" form="shipment-form" type="submit">Save shipment</button>`);$('#shipment-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.reference.trim()||!data.customer.trim())return;Object.keys(data).forEach(k=>data[k]=data[k].trim());if(state.shipments.some(x=>x.id!==id&&x.reference.toLowerCase()===data.reference.toLowerCase()))return toast('That shipment reference already exists.');if(id)Object.assign(s,data);else state.shipments.push({...data,id:uid()});save();$('#detail').close();render();toast('Shipment saved');};}
function publicHTML(snapshot){return `<div class="public-preview"><div class="eyebrow">N10 LOGISTICS · SHIPMENT UPDATE</div><h2>${esc(snapshot.reference)}</h2><p class="muted">${esc(snapshot.customer)}</p><h3>${esc(snapshot.status)}</h3><p>${esc(snapshot.update||'An update will be provided shortly.')}</p>${snapshot.milestones.map(m=>`<div class="milestone"><span>${esc(m.title)}</span><strong>${esc(m.status)}</strong></div>`).join('')}<p class="muted">Next update: ${esc(fmt(snapshot.nextUpdate))}</p><small class="muted">Snapshot generated ${esc(fmt(new Date().toISOString()))}. This is not live tracking.</small></div>`;}
function customerView(id){const s=shipment(id),snap=customerSnapshot(s,state.tasks);openDialog('Customer update preview',`<div class="notice" style="margin-bottom:18px">Only the approved fields below are exported. Internal notes, assignees, rates, email bodies, and private tasks are excluded. This version exports a snapshot; secure live links are not available yet.</div>${publicHTML(snap)}`,`<button id="edit-public">Edit update</button><button id="copy-public">Copy update</button><button id="export-public" class="primary">Download customer update</button>`);$('#edit-public').onclick=()=>shipmentEditor(id);$('#copy-public').onclick=async()=>{const text=[snap.reference+' — '+snap.customer,snap.status,snap.update,...snap.milestones.map(m=>m.title+': '+m.status),'Next update: '+fmt(snap.nextUpdate)].join('\n\n');try{await navigator.clipboard.writeText(text);toast('Customer update copied');}catch{toast('Clipboard unavailable. Download the update instead.');}};$('#export-public').onclick=()=>download(`${s.reference.replace(/[^a-z0-9_-]/gi,'-')}-update.html`,`<!doctype html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shipment update</title><style>body{font:15px/1.7 system-ui;color:#244439;max-width:650px;margin:60px auto;padding:24px}h2{font-size:30px}.milestone{display:flex;justify-content:space-between;border-bottom:1px solid #dde5dd;padding:14px 0}.muted{color:#657768}.eyebrow{font-size:12px;letter-spacing:2px}</style>${publicHTML(snap)}</html>`,'text/html');}
function workloadHTML(){const active=state.tasks.filter(t=>t.status!=='Completed');return `<div class="notice">Workload reflects this local workspace. Team queues are filters; production user accounts and permissions are not configured.</div><div class="shipment-grid" style="margin-top:20px">${TEAMS.map(tm=>{const list=active.filter(t=>t.team===tm);return `<section class="panel"><div class="eyebrow">${esc(tm)}</div><h2>${list.length} open tasks</h2>${USERS.filter(u=>list.some(t=>t.owner===u)).map(u=>`<div class="loadbar"><strong>${esc(u)}</strong><div class="progress"><i style="width:${Math.min(100,list.filter(t=>t.owner===u).length/Math.max(1,...USERS.map(x=>active.filter(t=>t.owner===x).length))*100)}%"></i></div><span>${list.filter(t=>t.owner===u).length} tasks</span></div>`).join('')}<p class="muted">${list.filter(t=>t.due&&new Date(t.due)<new Date()).length} overdue · ${list.filter(t=>blockedBy(t,state.tasks).length).length} blocked</p><button data-queue="${esc(tm)}">Open ${esc(tm)} queue →</button></section>`;}).join('')}</div>`;}
function settingsHTML(){return `<div class="panel"><h2>Mailbox connections</h2><p class="muted">Choose your provider when configuring the production backend. No mailbox credentials are collected by this demo.</p><div class="shipment-grid">${['Microsoft 365 / Outlook','Gmail / Google Workspace'].map(x=>`<div class="notice"><strong>${x}</strong><br>Not connected · OAuth backend setup required<br>Planned: inbox sync, thread history, attachments, replies.</div>`).join('')}</div></div><div class="panel"><h2>Your workspace data</h2><p class="muted">Changes are saved in this browser. Export a backup to keep a copy or transfer it manually. This is not a shared team database.</p><div class="actions"><button id="export-data">Export workspace backup</button><button id="import-data">Restore backup</button><input id="backup-file" type="file" accept="application/json,.json" hidden><button id="reset-data" class="danger">Reset sample workspace</button></div></div><div class="panel"><h2>What comes next</h2><p class="muted">Shared database and sign-in → team permissions → email OAuth and sync → secure customer links and notification delivery.</p><p class="muted">Production setup requirements and the data model are documented in the repository.</p></div>`;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindPage(){document.querySelectorAll('[data-email]').forEach(b=>b.onclick=()=>{selectedEmail=b.dataset.email;render();});const e=state.emails.find(x=>x.id===selectedEmail);$('#open-linked')?.addEventListener('click',()=>taskDetail(e.taskId));$('#email-task')?.addEventListener('click',()=>{taskEditor(null,{emailId:e.id});$('#task-form').elements.title.value=e.subject;$('#task-form').elements.description.value=e.body;});$('#email-reply')?.addEventListener('click',()=>draftReply(e.id));$('#email-link')?.addEventListener('click',()=>{openDialog('Link to existing task',`<form id="existing-form"><label class="field">Task<select name="task">${state.tasks.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label></form>`,`<button class="primary" type="submit" form="existing-form">Link task</button>`);$('#existing-form').onsubmit=ev=>{ev.preventDefault();const id=new FormData(ev.target).get('task');if(!id)return toast('Create a task first.');e.taskId=id;save();$('#detail').close();render();};});document.querySelectorAll('[data-shipment]').forEach(b=>b.onclick=()=>{page='workspace';query=shipment(b.dataset.shipment).reference;team='All teams';owner='All owners';attention=false;render();});document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>customerView(b.dataset.customer));document.querySelectorAll('[data-edit-shipment]').forEach(b=>b.onclick=()=>shipmentEditor(b.dataset.editShipment));document.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>{page='workspace';team=b.dataset.queue;attention=false;render();});$('#export-data')?.addEventListener('click',()=>download('inboxy-backup.json',JSON.stringify(state,null,2),'application/json'));$('#import-data')?.addEventListener('click',()=>$('#backup-file').click());$('#backup-file')?.addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;if(file.size>5000000)return toast('Backup must be under 5 MB.');try{const data=JSON.parse(await file.text());validateBackup(data);if(!confirm('Replace this browser’s workspace with this backup? Export your current data first if needed.'))return;state=migrateWorkspace(data);syncDirectory();save();render();toast('Backup restored');}catch{toast('Invalid backup. Current workspace was kept.');}});$('#reset-data')?.addEventListener('click',()=>{if(!confirm('Replace all local changes with sample data? Export a backup first if needed.'))return;state=migrateWorkspace(seed());syncDirectory();save();render();toast('Sample workspace restored');});}
function validateBackup(data){if(data.groups&&(!Array.isArray(data.groups)||!data.groups.length||data.groups.some(g=>typeof g.id!=='string'||typeof g.name!=='string'||!g.name.trim()||typeof g.description!=='string'||!Array.isArray(g.members)||g.members.some(m=>typeof m!=='string'))||new Set(data.groups.map(g=>g.name.toLowerCase())).size!==data.groups.length))throw Error();if(data.people&&(!Array.isArray(data.people)||data.people.some(p=>typeof p.id!=='string'||typeof p.name!=='string'||typeof p.email!=='string'||!['Admin','Member'].includes(p.role))||new Set(data.people.map(p=>p.name.toLowerCase())).size!==data.people.length))throw Error();if(data.version!==1||!['tasks','shipments','emails','drafts'].every(k=>Array.isArray(data[k])))throw Error();const ids=new Set();for(const x of [...data.tasks,...data.shipments,...data.emails,...data.drafts]){if(typeof x.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(x.id)||ids.has(x.id))throw Error();ids.add(x.id);}const tasks=new Set(data.tasks.map(t=>t.id)),ships=new Set(data.shipments.map(s=>s.id));for(const t of data.tasks){if(!['title','description','nextAction','owner','team','status','priority','due','followUp'].every(k=>typeof t[k]==='string')||!(data.groups?.map(g=>g.name)||DEFAULT_TEAMS).includes(t.team)||!STATUSES.includes(t.status)||!['Unassigned',...(data.people?.map(p=>p.name)||DEFAULT_USERS)].includes(t.owner)||!['Urgent','High','Normal','Low'].includes(t.priority)||!Array.isArray(t.notes)||!Array.isArray(t.activity)||!Array.isArray(t.dependencies)||t.dependencies.some(id=>!tasks.has(id))||(t.parentId&&!tasks.has(t.parentId))||(t.shipmentId&&!ships.has(t.shipmentId)))throw Error();}for(const t of data.tasks){let p=t.parentId;const seen=new Set([t.id]);while(p){if(seen.has(p))throw Error();seen.add(p);p=data.tasks.find(x=>x.id===p)?.parentId;}const walk=(id,path)=>{if(path.has(id))throw Error();const next=new Set([...path,id]);data.tasks.find(x=>x.id===id).dependencies.forEach(d=>walk(d,next));};walk(t.id,new Set());}for(const s of data.shipments)if(!['reference','customer','route','container','publicStatus','publicUpdate','nextUpdate'].every(k=>typeof s[k]==='string'))throw Error();for(const e of data.emails)if(!['from','subject','body','date'].every(k=>typeof e[k]==='string')||(e.taskId&&!tasks.has(e.taskId)))throw Error();}
save();render();setInterval(()=>{if(!$('#detail').open&&page==='workspace'&&document.activeElement?.tagName!=='INPUT')render();},60000);

function overviewHTML(active){const overdue=active.filter(t=>t.due&&new Date(t.due)<new Date()).length;return `<section class="pulse-bar"><div><span class="pulse-dot"></span><strong>Operation in motion</strong><span class="pulse-label">A live view of this workspace</span></div><div class="pulse-metrics"><span><b>${active.length}</b> open</span><span><b class="orange">${overdue}</b> overdue</span><span><b>${active.filter(t=>blockedBy(t,state.tasks).length).length}</b> blocked</span><span><b>${state.groups.length}</b> groups</span></div></section>`;}
function focusHTML(list){const active=list.filter(t=>t.status!=='Completed'),first=active[0],rest=active.slice(1);return `<div class="focus-layout"><section class="action-stream"><div class="section-kicker"><span>01 / THE NEXT MOVE</span><span>Ranked by operational impact</span></div>${first?`<article class="spotlight" data-task="${first.id}" role="button" tabindex="0"><div class="spotlight-top"><span class="live-pill">PRIORITY ${esc(first.priority.toUpperCase())}</span><span>${esc(shipment(first.shipmentId)?.reference||'GENERAL REQUEST')}</span></div><h2>${esc(first.title)}</h2><p>${esc(first.nextAction||'Set the next action to move this forward.')}</p><div class="spotlight-footer"><span class="avatar">${esc(initials(first.owner))}</span><span>${esc(first.owner)}<small>${esc(first.team)}</small></span><span class="spotlight-reason">${esc(priority(first,state.tasks).reasons.slice(0,2).join(' · '))}</span><span class="arrow-disc">↗</span></div></article>`:'<div class="panel"><h2>A clear runway.</h2><p class="muted">No open work in this view.</p></div>'}<div class="section-kicker next-kicker"><span>02 / ON YOUR RADAR</span><span>${rest.length} open actions</span></div><div class="radar-list">${rest.map((t,i)=>`<button class="radar-row" data-task="${t.id}"><span class="radar-number">${String(i+2).padStart(2,'0')}</span><span class="radar-main"><strong>${esc(t.title)}</strong><small>${esc(shipment(t.shipmentId)?.reference||'General request')} <i>·</i> ${esc(t.team)} <i>·</i> ${esc(t.owner)}</small></span><span class="radar-status">${blockedBy(t,state.tasks).length?'Blocked':esc(t.status)}</span><span class="radar-arrow">↗</span></button>`).join('')}</div></section><aside class="team-orbit"><div class="section-kicker"><span>YOUR SPACES</span><button id="manage-spaces">Manage ↗</button></div>${state.groups.map((g,i)=>{const ts=state.tasks.filter(t=>t.team===g.name&&t.status!=='Completed');return `<button class="space-lane" data-queue="${esc(g.name)}"><span class="space-id">${String(i+1).padStart(2,'0')}</span><span class="space-main"><strong>${esc(g.name)}</strong><small>${g.members.length} ${g.members.length===1?'person':'people'} · ${ts.filter(t=>blockedBy(t,state.tasks).length).length} blocked</small></span><span class="space-total">${ts.length}</span></button>`;}).join('')}<div class="handoff-note"><span>↳</span><h3>Nothing falls between teams.</h3><p>Link the next action to its owner. Dependencies keep handoffs visible until the work is done.</p><button id="focus-new-group">Create a group +</button></div></aside></div>`;}
function groupsHTML(){return `<div class="directory-intro"><span class="directory-label">YOUR WORKSPACE, YOUR STRUCTURE</span><p>No preset departments. Build the groups that match the way you work.</p></div><div class="group-grid">${state.groups.map((g,i)=>{const tasks=state.tasks.filter(t=>t.team===g.name&&t.status!=='Completed');return `<article class="group-tile"><div class="group-tile-top"><span class="group-number">${String(i+1).padStart(2,'0')}</span><button data-edit-group="${esc(g.id)}" aria-label="Edit ${esc(g.name)}">↗</button></div><h2>${esc(g.name)}</h2><p>${esc(g.description||'Your team’s dedicated space.')}</p><div class="group-members">${g.members.slice(0,5).map(n=>`<span class="avatar" title="${esc(n)}">${esc(initials(n))}</span>`).join('')}<small>${g.members.length?g.members.length+(g.members.length===1?' person':' people'):'Add your people'}</small></div><div class="group-bottom"><span><b>${tasks.length}</b> open actions</span><button data-queue="${esc(g.name)}">Enter space →</button></div></article>`;}).join('')}<button class="group-create" id="tile-new-group"><span>＋</span><strong>Create a group</strong><small>Any team. Any workflow.</small></button></div><div class="people-heading"><div><span class="section-kicker">WORKSPACE DIRECTORY</span><h2>The people behind the work.</h2></div><button id="directory-add-person">＋ Add person</button></div><div class="notice">Profiles below are local assignment records. They do not create login accounts, send invitations, or grant access. Real accounts require the shared backend.</div><div class="people-list">${state.people.map(p=>`<button class="person-row" data-edit-person="${esc(p.id)}"><span class="avatar">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.email||'No email added')}</small></span><span class="person-groups">${state.groups.filter(g=>g.members.includes(p.name)).map(g=>esc(g.name)).join(' · ')||'No group assigned'}</span><span class="badge">${esc(p.role)} profile</span><span>↗</span></button>`).join('')}</div>`;}
function bindDirectory(){$('#manage-spaces')?.addEventListener('click',()=>{page='groups';render();});for(const id of ['focus-new-group','tile-new-group'])$('#'+id)?.addEventListener('click',()=>groupEditor());$('#directory-add-person')?.addEventListener('click',()=>personEditor());document.querySelectorAll('[data-edit-group]').forEach(b=>b.onclick=()=>groupEditor(b.dataset.editGroup));document.querySelectorAll('[data-edit-person]').forEach(b=>b.onclick=()=>personEditor(b.dataset.editPerson));}
function groupEditor(id){const g=state.groups.find(g=>g.id===id)||{name:'',description:'',members:[]};openDialog(id?'Edit group':'Create your group',`<form id="group-form" class="form-grid"><label class="field full">Group name<input name="name" required maxlength="60" value="${esc(g.name)}" placeholder="e.g. Ocean exports, Pricing, Dispatch"></label><label class="field full">What does this group handle?<textarea name="description" maxlength="300" placeholder="Give this space a clear purpose.">${esc(g.description)}</textarea></label><div class="full"><h3>Assign people</h3><p class="muted">Choose who belongs to this group.</p>${state.people.map(p=>`<label class="check-row"><input type="checkbox" name="members" value="${esc(p.name)}" ${g.members.includes(p.name)?'checked':''}>${esc(p.name)} <small class="muted">${esc(p.email)}</small></label>`).join('')}</div></form>`,`<button data-group-cancel>Cancel</button><button form="group-form" type="submit" class="primary">${id?'Save group':'Create group'}</button>`);$('[data-group-cancel]').onclick=()=>$('#detail').close();$('#group-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name||name.toLowerCase()==='all teams')return toast('Choose a group name other than All teams.');if(state.groups.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return toast('A group with that name already exists.');const data={name,description:f.get('description').trim(),members:f.getAll('members')};if(id){const old=g.name;state.tasks.filter(t=>t.team===old).forEach(t=>t.team=name);if(team===old)team=name;Object.assign(g,data);}else state.groups.push({...data,id:uid()});syncDirectory();save();$('#detail').close();render();toast(id?'Group updated':'Group created — ready for assignment');};}
function personEditor(id){const p=state.people.find(p=>p.id===id)||{name:'',email:'',role:'Member'};openDialog(id?'Edit person':'Add a person',`<div class="notice">Create a local profile for assignment. This does not create a login or send an invitation.</div><form id="person-form" class="form-grid" style="margin-top:20px"><label class="field full">Full name<input name="name" required maxlength="80" value="${esc(p.name)}" placeholder="Name used on assignments"></label><label class="field">Email<input name="email" type="email" value="${esc(p.email)}" placeholder="name@company.com"></label><label class="field">Profile role<select name="role">${options(['Member','Admin'],p.role)}</select></label><div class="full"><h3>Groups</h3>${state.groups.map(g=>`<label class="check-row"><input type="checkbox" name="groups" value="${esc(g.id)}" ${g.members.includes(p.name)?'checked':''}>${esc(g.name)}</label>`).join('')}</div></form>`,`<button data-person-cancel>Cancel</button><button form="person-form" type="submit" class="primary">Save person</button>`);$('[data-person-cancel]').onclick=()=>$('#detail').close();$('#person-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),email=f.get('email').trim();if(!name||['unassigned','all owners'].includes(name.toLowerCase()))return toast('Choose a valid person name.');if(state.people.some(x=>x.id!==id&&(x.name.toLowerCase()===name.toLowerCase()||(email&&x.email.toLowerCase()===email.toLowerCase()))))return toast('That name or email already exists.');const old=p.name;if(id){state.tasks.filter(t=>t.owner===old).forEach(t=>t.owner=name);if(owner===old)owner=name;Object.assign(p,{name,email,role:f.get('role')});}else state.people.push({id:uid(),name,email,role:f.get('role')});const selected=f.getAll('groups');for(const g of state.groups){g.members=g.members.filter(n=>n!==old&&n!==name);if(selected.includes(g.id))g.members.push(name);}syncDirectory();save();$('#detail').close();render();toast('Person saved — available for task assignment');};}

function newTaskRecord(data){return {id:uid(),title:data.title.trim(),team:data.team|| (team==='All teams'?TEAMS[0]:team),owner:data.owner||'Unassigned',status:data.status||'Up next',priority:data.priority||'Normal',due:data.due||'',followUp:data.followUp||'',nextAction:data.nextAction||'',description:data.description||'',shipmentId:data.shipmentId||'',parentId:data.parentId||null,dependencies:[],notes:[],activity:[{text:'Task created',date:new Date().toISOString()}],public:false,publicTitle:'',impact:false,boardOrder:state.tasks.filter(t=>t.status===(data.status||'Up next')).length};}
function quickTask(defaults={}){openDialog(defaults.parentId?'Add subtask':'What needs to happen?',`<form id="quick-task-form" class="form-grid"><label class="field full">Task<input name="title" required maxlength="180" placeholder="e.g. Wrap pallet 3 before pickup" autofocus></label><label class="field">Group<select name="team">${options(TEAMS,defaults.team||(team==='All teams'?TEAMS[0]:team))}</select></label><label class="field">Assign to<select name="owner">${options(USERS,owner==='All owners'?'Unassigned':owner)}</select></label><label class="field full">Next action<input name="nextAction" placeholder="e.g. Confirm ready with warehouse"></label><label class="field">Due<input name="due" type="datetime-local"></label><label class="field">Status<select name="status">${options(STATUSES,defaults.status||'Up next')}</select></label><details class="quick-more full"><summary>Shipment & instructions <span>Optional</span></summary><div class="form-grid"><label class="field full">Linked shipment<select name="shipmentId"><option value="">General request</option>${state.shipments.map(s=>`<option value="${s.id}" ${defaults.shipmentId===s.id?'selected':''}>${esc(s.reference+' · '+s.customer)}</option>`).join('')}</select></label><label class="field full">Instructions<textarea name="description" placeholder="Anything the assigned person needs to know"></textarea></label><label class="field">Priority<select name="priority">${options(['Normal','High','Urgent','Low'],'Normal')}</select></label><label class="field">Follow up<input name="followUp" type="datetime-local"></label></div></details></form>`,`<button data-quick-cancel>Cancel</button><button type="submit" form="quick-task-form" class="primary">Create task</button>`);$('[data-quick-cancel]').onclick=()=>$('#detail').close();$('#quick-task-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.title.trim())return toast('Add a task title.');const t=newTaskRecord({...data,parentId:defaults.parentId});state.tasks.push(t);save();$('#detail').close();render();toast(`Created in ${t.status}`);};}
function quickEdit(id){const t=state.tasks.find(t=>t.id===id);openDialog('Quick edit',`<p class="quick-edit-title">${esc(t.title)}</p><form id="quick-edit-form" class="form-grid"><label class="field full">Next action<input name="nextAction" value="${esc(t.nextAction)}" placeholder="What happens next?"></label><label class="field">Assign to<select name="owner">${options(USERS,t.owner)}</select></label><label class="field">Group<select name="team">${options(TEAMS,t.team)}</select></label><label class="field">Due<input name="due" type="datetime-local" value="${esc(t.due)}"></label><label class="field">Follow up<input name="followUp" type="datetime-local" value="${esc(t.followUp)}"></label></form>`,`<button id="quick-full-detail">Full details</button><button type="submit" form="quick-edit-form" class="primary">Save</button>`);$('#quick-full-detail').onclick=()=>taskDetail(id);$('#quick-edit-form').onsubmit=e=>{e.preventDefault();Object.assign(t,Object.fromEntries(new FormData(e.target)));activity(t,'Next action and assignment updated');save();$('#detail').close();render();toast('Task updated');};}
function applyBoardMove(id,status,beforeId=null){const t=state.tasks.find(t=>t.id===id);if(!t)return;const old=t.status;const issue=moveTask(state.tasks,id,status,beforeId);if(issue){toast(issue);render();return;}activity(t,old===status?'Reordered on board':`Moved from ${old} to ${status}`);save();render();toast(old===status?'Card reordered':`Moved to ${status}`);}
let dragId=null,dragGhost=null,dragStart=null,dragLast=null,dragFrame=null;
function dropTarget(x,y){const el=document.elementFromPoint(x,y);const col=el?.closest('[data-status]');if(!col)return null;const cards=[...col.querySelectorAll('.operation-card')].filter(c=>c.dataset.task!==dragId);const before=cards.find(c=>y<c.getBoundingClientRect().top+c.getBoundingClientRect().height/2);return {col,status:col.dataset.status,beforeId:before?.dataset.task||null};}
function clearDrag(){dragId=null;dragGhost?.remove();dragGhost=null;dragStart=null;dragLast=null;cancelAnimationFrame(dragFrame);dragFrame=null;document.body.classList.remove('is-dragging');document.querySelectorAll('.drop-over,.drag-source,.drop-before,.drop-at-end').forEach(e=>e.classList.remove('drop-over','drag-source','drop-before','drop-at-end'));}
function bindBoard(){
 document.querySelectorAll('[data-add-status]').forEach(b=>b.onclick=()=>quickTask({status:b.dataset.addStatus}));
 document.querySelectorAll('[data-quick-status]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const title=new FormData(f).get('title').trim();if(!title)return;const status=f.dataset.quickStatus;state.tasks.push(newTaskRecord({title,status,owner:owner==='All owners'?'Unassigned':owner}));save();render();const input=[...document.querySelectorAll('[data-quick-status]')].find(x=>x.dataset.quickStatus===status)?.querySelector('input');input?.focus();toast('Task created — click NEXT to add the next action');});
 document.querySelectorAll('[data-quick-edit]').forEach(b=>b.onclick=()=>quickEdit(b.dataset.quickEdit));
 document.querySelectorAll('[data-card-email]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.cardEmail));
 document.querySelectorAll('[data-move]').forEach(s=>s.onchange=()=>applyBoardMove(s.dataset.move,s.value));
 document.querySelectorAll('.operation-card').forEach(c=>{c.ondragstart=e=>{if(e.target.closest('select,input,button')){e.preventDefault();return;}dragId=c.dataset.task;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';c.classList.add('drag-source');};c.ondragend=clearDrag;});
 document.querySelectorAll('[data-status]').forEach(col=>{col.ondragover=e=>{if(!dragId)return;e.preventDefault();e.dataTransfer.dropEffect='move';paintDrop(dropTarget(e.clientX,e.clientY));};col.ondragleave=e=>{if(!col.contains(e.relatedTarget))paintDrop(null);};col.ondrop=e=>{if(!dragId)return;e.preventDefault();const id=dragId,target=dropTarget(e.clientX,e.clientY);clearDrag();if(target)applyBoardMove(id,target.status,target.beforeId);};});
 document.querySelectorAll('[data-drag]').forEach(handle=>{handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();clearDrag();dragId=handle.dataset.drag;dragStart={x:e.clientX,y:e.clientY};dragLast={x:e.clientX,y:e.clientY};handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(dragId!==handle.dataset.drag||!dragStart)return;e.preventDefault();dragLast={x:e.clientX,y:e.clientY};if(!dragGhost&&Math.hypot(e.clientX-dragStart.x,e.clientY-dragStart.y)>5){const card=handle.closest('.operation-card');dragGhost=card.cloneNode(true);dragGhost.removeAttribute('data-task');dragGhost.setAttribute('aria-hidden','true');dragGhost.classList.add('drag-ghost');dragGhost.style.width=card.getBoundingClientRect().width+'px';document.body.append(dragGhost);card.classList.add('drag-source');document.body.classList.add('is-dragging');const tick=()=>{if(!dragGhost||!dragLast)return;const board=$('.board'),r=board.getBoundingClientRect();if(dragLast.x>r.right-65)board.scrollLeft+=12;else if(dragLast.x<r.left+65)board.scrollLeft-=12;if(dragLast.y>innerHeight-70)window.scrollBy(0,10);else if(dragLast.y<70)window.scrollBy(0,-10);paintDrop(dropTarget(dragLast.x,dragLast.y));dragFrame=requestAnimationFrame(tick);};dragFrame=requestAnimationFrame(tick);}if(dragGhost){dragGhost.style.left=(e.clientX-40)+'px';dragGhost.style.top=(e.clientY-25)+'px';paintDrop(dropTarget(e.clientX,e.clientY));}};handle.onpointerup=e=>{if(dragId!==handle.dataset.drag)return;const id=dragId,target=dragGhost?dropTarget(e.clientX,e.clientY):null;clearDrag();if(target)applyBoardMove(id,target.status,target.beforeId);};handle.onpointercancel=clearDrag;handle.onclick=e=>e.stopPropagation();});
}

function paintDrop(target){
 document.querySelectorAll('.drop-over,.drop-before,.drop-at-end').forEach(el=>el.classList.remove('drop-over','drop-before','drop-at-end'));
 if(!target)return;
 target.col.classList.add('drop-over');
 const before=[...target.col.querySelectorAll('.operation-card')].find(c=>c.dataset.task===target.beforeId);
 if(before)before.classList.add('drop-before');
 else target.col.querySelector('.column-cards').classList.add('drop-at-end');
}
